mapper.update:
/* updateSrngGrdngPopGrdng (면접심사채점표(드림) 타당도및임상도척도 수정) - Lee Hye Sun */
UPDATE AFA140 SET
      TRPR_INFO_NO = #{TRPR_INFO_NO}
    , APLY_RCPT_SN =  #{APLY_RCPT_SN}
    , GRDNG_PRVSON_SCORE1 = #{GRDNG_PRVSON_SCORE1}
    , GRDNG_PRVSON_SCORE2 = #{GRDNG_PRVSON_SCORE2}
    , GRDNG_PRVSON_SCORE3 = #{GRDNG_PRVSON_SCORE3}
    , GRDNG_PRVSON_SCORE4 = #{GRDNG_PRVSON_SCORE4}
    , GRDNG_PRVSON_SCORE5 = #{GRDNG_PRVSON_SCORE5}
    , GRDNG_PRVSON_SCORE6 = #{GRDNG_PRVSON_SCORE6}
    , GRDNG_PRVSON_SCORE7 = #{GRDNG_PRVSON_SCORE7}
    , GRDNG_PRVSON_SCORE8 = #{GRDNG_PRVSON_SCORE8}
    , GRDNG_PRVSON_SCORE9 = #{GRDNG_PRVSON_SCORE9}
    , GRDNG_PRVSON_SCORE10 = #{GRDNG_PRVSON_SCORE10}
    , GRDNG_PRVSON_SCORE11 = #{GRDNG_PRVSON_SCORE11}
    , GRDNG_PRVSON_SCORE12 = #{GRDNG_PRVSON_SCORE12}
    , GRDNG_PRVSON_SCORE13 = #{GRDNG_PRVSON_SCORE13}
    , GRDNG_PRVSON_SCORE14 = #{GRDNG_PRVSON_SCORE14}
    , GRDNG_PRVSON_SCORE15 = #{GRDNG_PRVSON_SCORE15}
    , GRDNG_PRVSON_SCORE16 = #{GRDNG_PRVSON_SCORE16}
    , GRDNG_PRVSON_SCORE17 = #{GRDNG_PRVSON_SCORE17}
    , GRDNG_CN = #{GRDNG_CN}
    , FRST_RGTR_ID = (SELECT FRST_RGTR_ID FROM AFA140
                    WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}
                    AND APLY_RCPT_SN = #{APLY_RCPT_SN})
    , FRST_REG_DT = (SELECT FRST_REG_DT FROM AFA140
                    WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}
                    AND APLY_RCPT_SN = #{APLY_RCPT_SN})
    , LAST_MDFR_ID = #{LAST_MDFR_ID}
    , LAST_MDFCN_DT = SYSDATE
WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}
AND APLY_RCPT_SN =  #{APLY_RCPT_SN}

mapper.select:
/* selectPtcptList (면접심사채점표(드림) 대상자문제상태 조회)) - Lee Hye Sun */ SELECT A.TRPR_INFO_NO --대상자정보번호 , A.APLY_RCPT_SN --신청접수일련번호 , DEC_B64(X.RRNO_ENCPT) AS RRNO_ENCPT --주민등록번호암호화 , DEC_B64(B.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT --대상자명암호화 , A.TRPR_PHOTO_ATFINO , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SXDC_SE_CD' AND CMMNS_CD_VALUE = B.SXDC_SE_CD) AS SXDC --성별 , B.TRPR_BRTH_YMD --생년월일 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'PBLAST_SE_CD' AND CMMNS_CD_VALUE = B.PBLAST_SE_CD) AS PBLAST --공적부조 , DEC_B64(B.EML_ADDR_ENCPT) AS EML_ADDR_ENCPT --이메일 , '만 ' || TRUNC(MONTHS_BETWEEN(SYSDATE, B.TRPR_BRTH_YMD) /12) || '세' AS TRPRAGE --만나이 , B.PST_ADDR || B.DADDR AS ADDR --주소 , DEC_B64(B.MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT --대상자 휴대전화 , B.TRPR_TELNO AS TRPR_TELNO --대상자 전화번호 , CASE WHEN G.SCHULW_DSCNTC_YMD IS NOT NULL THEN G.SCHULW_DSCNTC_YMD END AS SCHULW_DSCNTC_YMD --학업중단일 , CASE WHEN G.SCHULW_DSCNTC_YMD IS NOT NULL THEN G.ACBG_SE_CD || ' ' || G.GRADE_SE_CD END AS DSCNTC_ACBG --학업중단당시 학년 , CASE WHEN G.DSCNTC_SCLAS IS NOT NULL THEN G.DSCNTC_LCLAS || ' (' || G.DSCNTC_SCLAS || ')' ELSE G.DSCNTC_LCLAS END AS DSCNTC_CN --학업중단사유
, DEC_B64(B.PRTCR_NM_ENCPT) AS PRTCR_NM_ENCPT --보호자명 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'FAM_REL_SE_CD' AND CMMNS_CD_VALUE = B.FAM_REL_SE_CD) AS FAM_REL_SE_CD --가족관계 , DEC_B64(B.PRTCR_MBL_TELNO_ENCPT) AS PRTCR_MBL_TELNO_ENCPT --보호자 전화번호 , DEC_B64(B.PRTCR_EML_ADDR_ENCPT) AS PRTCR_EML_ADDR_ENCPT --보호자 이메일 , B.PRTCR_PST_ADDR || B.PRTCR_DADDR AS PRTCR_ADDR --보호자 우편주소
, A.RQST_INST_NM --의뢰기관명 , DEC_B64(A.PIC_TELNO_ENCPT) AS PIC_TELNO_ENCPT --의뢰담당자 전화번호 , DEC_B64(A.PIC_NM_ENCPT) AS PIC_NM_ENCPT --의뢰담당자 이름 , DEC_B64(A.PIC_EML_ADDR_ENCPT) AS PIC_EML_ADDR_ENCPT --의뢰담당자 이메일 , DEC_B64(A.PIC_MBL_TELNO_ENCPT) AS PIC_MBL_TELNO_ENCPT --의뢰담당자 핸드폰번호 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'RCPT_RQST_COURS_SE_CD' AND CMMNS_CD_VALUE = A.RCPT_RQST_COURS_SE_CD) AS RCPT_RQST_COURS --의뢰담당자 의뢰경로
, B.RESIDE_SHAPE_SE_CD --주거형태구분코드 , B.PBLAST_SE_CD --공적부조구분코드 , B.FAM_SHAPE_SE_CD --가족형태구분코드
, CASE WHEN C.SCHL_NM IS NOT NULL THEN C.SCHL_NM || ' (' || C.ACBG_SE_CD || ') ' || C.GRADE_SE_CD || ' ' || C.GRDTN_STTS_SE_CD ELSE NULL END AS SCHL --학력사항 , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'FAM_SHAPE_SE_CD' AND CMMNS_CD_VALUE = B.FAM_SHAPE_SE_CD ) AS FAM_SHAPE --가족형태 , CASE D.SMKNG_YN_SE_CD WHEN '1' THEN CASE WHEN D.AMOFSM_DTL_NM IS NOT NULL THEN (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SMKNG_YN_SE_CD' AND CMMNS_CD_VALUE = D.SMKNG_YN_SE_CD) || ' (흡연량 : ' || D.AMOFSM_DTL_NM || ')' ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SMKNG_YN_SE_CD' AND CMMNS_CD_VALUE = D.SMKNG_YN_SE_CD) END ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SMKNG_YN_SE_CD' AND CMMNS_CD_VALUE = D.SMKNG_YN_SE_CD) END AS SMKNG --흡연 , CASE D.DRNKG_YN_SE_CD WHEN '1' THEN CASE WHEN D.VOOFDR_DTL_NM IS NOT NULL THEN (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'DRNKG_YN_SE_CD' AND CMMNS_CD_VALUE = D.DRNKG_YN_SE_CD) || ' (음주량 : ' || D.VOOFDR_DTL_NM || ')' ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'DRNKG_YN_SE_CD' AND CMMNS_CD_VALUE = D.DRNKG_YN_SE_CD) END ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'DRNKG_YN_SE_CD' AND CMMNS_CD_VALUE = D.DRNKG_YN_SE_CD) END AS DRNKG --음주 , CASE WHEN E.DSCSN = '없음' THEN E.DSCSN WHEN E.DSCSN IS NULL THEN NULL ELSE E.DSCSN || ' (기간 : ' || D.DSCSN_PRD_NM || ', 횟수 : ' || D.DSCSN_CONT || ')' END AS DSCSN --상담경험 , CASE WHEN D.DEVLPA_TROBL_SE_CD = '99' THEN (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'DEVLPA_TROBL_SE_CD' AND CMMNS_CD_VALUE = D.DEVLPA_TROBL_SE_CD) || ' (' || D.DEVLPA_TROBL_ETC_NM || ')' ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'DEVLPA_TROBL_SE_CD' AND CMMNS_CD_VALUE = D.DEVLPA_TROBL_SE_CD) END AS DEVLPA --발달장애여부 , F.DISS --질병상태 , CASE D.NOW_TAKNG_DRFSTF_YN_SE_CD WHEN '1' THEN CASE WHEN D.NOW_TAKNG_PRD_NM IS NOT NULL THEN (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'NOW_TAKNG_DRFSTF_YN_SE_CD' AND CMMNS_CD_VALUE = D.NOW_TAKNG_DRFSTF_YN_SE_CD) || ' (복용기간 : ' || D.NOW_TAKNG_PRD_NM || ', 약물명 : ' || D.NOW_TAKNG_DRFSTF_NM || ')' ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'NOW_TAKNG_DRFSTF_YN_SE_CD' AND CMMNS_CD_VALUE = D.NOW_TAKNG_DRFSTF_YN_SE_CD) END ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'NOW_TAKNG_DRFSTF_YN_SE_CD' AND CMMNS_CD_VALUE = D.NOW_TAKNG_DRFSTF_YN_SE_CD) END AS DRFSF --현재약물복용 , CASE D.SUCDE_CTPV_YN_SE_CD WHEN '1' THEN CASE WHEN D.SUCDE_CTPV_CONT IS NOT NULL THEN (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SUCDE_CTPV_YN_SE_CD' AND CMMNS_CD_VALUE = D.SUCDE_CTPV_YN_SE_CD) || ' (횟수 : ' || D.SUCDE_CTPV_CONT || ', 방법 : ' || D.SUCDE_CTPV_ETC_NM || ')' WHEN D.SUCDE_CTPV_ETC_NM IS NOT NULL THEN (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SUCDE_CTPV_YN_SE_CD' AND CMMNS_CD_VALUE = D.SUCDE_CTPV_YN_SE_CD) || ' (횟수 : ' || D.SUCDE_CTPV_CONT || ', 방법 : ' || D.SUCDE_CTPV_ETC_NM || ')' ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SUCDE_CTPV_YN_SE_CD' AND CMMNS_CD_VALUE = D.SUCDE_CTPV_YN_SE_CD) END ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SUCDE_CTPV_YN_SE_CD' AND CMMNS_CD_VALUE = D.SUCDE_CTPV_YN_SE_CD) END AS SUCDE --자살시도여부 , CASE D.SLFIJR_CTPV_YN_SE_CD WHEN '1' THEN CASE WHEN D.SLFIJR_CTPV_CONT IS NOT NULL THEN (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SLFIJR_CTPV_YN_SE_CD' AND CMMNS_CD_VALUE = D.SLFIJR_CTPV_YN_SE_CD) || ' (횟수 : ' || D.SLFIJR_CTPV_CONT || ', 방법 : ' || D.SLFIJR_CTPV_ETC_NM || ')' WHEN D.SUCDE_CTPV_ETC_NM IS NOT NULL THEN (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SLFIJR_CTPV_YN_SE_CD' AND CMMNS_CD_VALUE = D.SLFIJR_CTPV_YN_SE_CD) || ' (횟수 : ' || D.SLFIJR_CTPV_CONT || ', 방법 : ' || D.SLFIJR_CTPV_ETC_NM || ')' ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SUCDE_CTPV_YN_SE_CD' AND CMMNS_CD_VALUE = D.SUCDE_CTPV_YN_SE_CD) END ELSE (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'SLFIJR_CTPV_YN_SE_CD' AND CMMNS_CD_VALUE = D.SLFIJR_CTPV_YN_SE_CD) END AS SLFIJR --자해시도여부 , CASE WHEN D.INTLGN_INSP_RESULT_NM IS NOT NULL THEN D.INTLGN_INSP_RESULT_NM || '(' || '유형 : ' || D.INSP_TYPE_NM || ') 지능점수 : ' || D.INSP_RESULT_SCORE || '점' ELSE NULL END AS INSP --지능검사 FROM AFA100 A /*신청접수*/ LEFT JOIN SEA200 B /*대상자정보*/ ON A.TRPR_INFO_NO = B.TRPR_INFO_NO LEFT JOIN SCA300 X ON B.INDV_IDNTFC_NO = X.INDV_IDNTFC_NO LEFT JOIN ( SELECT SCHL_NM, GRADE_SE_CD, GRDTN_STTS_SE_CD, ACBG_SE_CD, TRPR_INFO_NO FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY E.SRTNG_SQNCE DESC, D.SRTNG_SQNCE DESC) ROW_NO, B.SCHL_NM AS SCHL_NM , C.CMMNS_CD_VALUE_NM AS GRADE_SE_CD , D.CMMNS_CD_VALUE_NM AS GRDTN_STTS_SE_CD , E.CMMNS_CD_VALUE_NM AS ACBG_SE_CD , A.TRPR_INFO_NO FROM SEA200 A JOIN SEA230 B ON A.TRPR_INFO_NO = B.TRPR_INFO_NO LEFT JOIN SAC100 C ON C.CMMNS_CD_ID = 'GRADE_SE_CD' AND C.CMMNS_CD_VALUE = B.GRADE_SE_CD LEFT JOIN SAC100 D ON D.CMMNS_CD_ID = 'GRDTN_STTS_SE_CD' AND D.CMMNS_CD_VALUE = B.GRDTN_STTS_SE_CD LEFT JOIN SAC100 E ON E.CMMNS_CD_ID = 'ACBG_SE_CD' AND E.CMMNS_CD_VALUE = B.ACBG_SE_CD WHERE 1=1 AND B.DEL_YN = 'N' ) AA WHERE ROW_NO = 1 ) C ON A.TRPR_INFO_NO = C.TRPR_INFO_NO LEFT JOIN ( SELECT * FROM( SELECT ROW_NUMBER() OVER(PARTITION BY A.TRPR_INFO_NO ORDER BY B.SCHULW_DSCNTC_YMD DESC) ROW_NO , B.SCHULW_DSCNTC_YMD , C.CMMNS_CD_VALUE_NM AS GRADE_SE_CD , D.CMMNS_CD_VALUE_NM AS ACBG_SE_CD , A.TRPR_INFO_NO , E.CMMNS_CD_VALUE_NM AS DSCNTC_LCLAS , F.CMMNS_CD_VALUE_NM AS DSCNTC_SCLAS FROM SEA200 A JOIN SEA240 B ON A.TRPR_INFO_NO = B.TRPR_INFO_NO LEFT JOIN SAC100 C ON C.CMMNS_CD_ID = 'GRADE_SE_CD' AND C.CMMNS_CD_VALUE = B.GRADE_SE_CD LEFT JOIN SAC100 D ON D.CMMNS_CD_ID = 'ACBG_SE_CD' AND D.CMMNS_CD_VALUE = B.ACBG_SE_CD LEFT JOIN SAC100 E ON E.CMMNS_CD_ID = 'DSCNTC_CS_LCLAS_SE_CD' AND E.CMMNS_CD_VALUE = B.DSCNTC_CS_LCLAS_SE_CD LEFT JOIN SAC100 F ON F.CMMNS_CD_ID = 'DSCNTC_CS_SCLAS_SE_CD' AND F.CMMNS_CD_VALUE = B.DSCNTC_CS_SCLAS_SE_CD WHERE 1=1 AND B.DEL_YN = 'N' ) AA WHERE ROW_NO = 1 ) G ON A.TRPR_INFO_NO = G.TRPR_INFO_NO LEFT JOIN AFA120 D /*대상자문제상태내역*/ ON A.TRPR_INFO_NO = D.TRPR_INFO_NO AND A.APLY_RCPT_SN = D.APLY_RCPT_SN LEFT JOIN ( SELECT CC.COMPNO_CHC_TYPE_MNG_NO , LISTAGG(BB.CMMNS_CD_VALUE_NM, ',') WITHIN GROUP(ORDER BY BB.CMMNS_CD_VALUE_NM) AS DSCSN FROM AFA120 CC JOIN AFA131 AA ON CC.COMPNO_CHC_TYPE_MNG_NO = AA.COMPNO_CHC_TYPE_MNG_NO JOIN SAC100 BB ON BB.CMMNS_CD_ID = 'COMPNO_TYPE_SCLAS_SE_CD' AND BB.CMMNS_CD_VALUE = AA.COMPNO_TYPE_SCLAS_SE_CD WHERE AA.COMPNO_TYPE_MLSFC_SE_CD = '0104' GROUP BY CC.COMPNO_CHC_TYPE_MNG_NO ) E ON E.COMPNO_CHC_TYPE_MNG_NO = D.COMPNO_CHC_TYPE_MNG_NO LEFT JOIN ( SELECT CC.COMPNO_CHC_TYPE_MNG_NO , LISTAGG( CASE WHEN BB.CMMNS_CD_VALUE_NM LIKE '기타' THEN BB.CMMNS_CD_VALUE_NM || '(' || AA.COMPNO_CHC_TYPE_ETC_NM || ')' ELSE BB.CMMNS_CD_VALUE_NM END, ',') WITHIN GROUP(ORDER BY BB.CMMNS_CD_VALUE_NM DESC) AS DISS FROM AFA120 CC JOIN AFA131 AA ON CC.COMPNO_CHC_TYPE_MNG_NO = AA.COMPNO_CHC_TYPE_MNG_NO JOIN SAC100 BB ON BB.CMMNS_CD_ID = 'COMPNO_TYPE_SCLAS_SE_CD' AND BB.CMMNS_CD_VALUE = AA.COMPNO_TYPE_SCLAS_SE_CD WHERE AA.COMPNO_TYPE_MLSFC_SE_CD = '0201' GROUP BY CC.COMPNO_CHC_TYPE_MNG_NO ) F ON F.COMPNO_CHC_TYPE_MNG_NO = D.COMPNO_CHC_TYPE_MNG_NO
WHERE A.TRPR_INFO_NO = #{TRPR_INFO_NO} AND A.APLY_RCPT_SN = #{APLY_RCPT_SN}
